function format(template: string, vars: Record<string, string | number>): string {
  return template.replace(/\{([a-zA-Z]+)\}/g, (whole, key: string) => String(vars[key] ?? whole));
}

const localeTag = (locale: PublicLocale) => locale === "pt" ? "pt-BR" : locale === "es" ? "es-ES" : locale === "zh" ? "zh-CN" : "en-US";
const pct = (bps: number, locale: PublicLocale) => `${(bps / 100).toLocaleString(localeTag(locale))}%`;
const num = (value: number, locale: PublicLocale) => value.toLocaleString(localeTag(locale));

export function foundersPublicCopy(locale: PublicLocale, facts: FoundersPublicFacts): FoundersPublicCopy {
  const byTier = new Map(facts.tiers.map((item) => [item.tier, item]));
  const free = byTier.get("free")!;
  const vars: Record<string, string | number> = {
    premiumMonths: facts.founder.premiumMonths,
    networks: facts.networks.available.join(", "),
    roadmapNetworks: facts.networks.roadmap.join(", "),
    allowHours: facts.sale.allowlistHours,
    calendarDays: facts.sale.calendarDays,
    allowLimits: `Pro ${facts.sale.allowlistLimits.pro}, Trader ${facts.sale.allowlistLimits.trader}, Pilot ${facts.sale.allowlistLimits.pilot}`,
    totalLimits: `Pro ${facts.sale.eventLimits.pro}, Trader ${facts.sale.eventLimits.trader}, Pilot ${facts.sale.eventLimits.pilot}`,
    freeZion: free.zionPerDay,
    freeBacktests: free.backtestsPer24h,
    freeHistory: free.historyDays,
    zionLimits: facts.tiers.map((item) => `${UI[locale].tierCopy[item.tier].name} ${item.zionPerDay}`).join(" · "),
    pilotBacktests: num(facts.pilotStandard.backtestsPerRollingWindow, locale),
    pilotHours: facts.pilotStandard.rollingHours,
    pilotAssets: facts.pilotStandard.maxAssets,
    pilotDays: facts.pilotStandard.maxHistoryDays,
    pilotCandle: facts.pilotStandard.candle,
    feeLimits: facts.tiers.map((item) => `${UI[locale].tierCopy[item.tier].name} ${pct(item.evmFeeBps, locale)}`).join(" · "),
  };
  return {
    ...UI[locale],
    faqs: FAQ_SEEDS.map((item) => ({ id: item.id, category: item.category, question: format(item.q[locale], vars), answer: format(item.a[locale], vars), decisionPending: item.pending })),
  };
}

export const FOUNDERS_PUBLIC_FAQ_COUNT = FAQ_SEEDS.length;
export const FOUNDERS_PUBLIC_FAQ_IDS = FAQ_SEEDS.map((item) => item.id);
